import React, { useState } from 'react';
import {
  Container,
  Grid,
  Paper,
  Typography,
  Button,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  Box,
  Card,
  CardContent,
  IconButton,
  Tooltip,
  CircularProgress,
  Alert,
  Divider,
  Tab,
  Tabs,
} from '@mui/material';
import {
  AutoAwesome,
  ContentCopy,
  Refresh,
  Download,
  Favorite,
  FavoriteBorder,
  Add,
  Close,
  Check,
} from '@mui/icons-material';
import { useMutation } from 'react-query';
import { generatorService } from '../services/api';
import { toast } from 'react-hot-toast';
import { useAuth } from '../context/AuthContext';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import { motion } from 'framer-motion';

const Generator = () => {
  const { user } = useAuth();
  const [productData, setProductData] = useState({
    product_name: '',
    category: '',
    brand: '',
    features: [],
    target_audience: 'general audience',
    tone: 'professional',
    keywords: [],
    language: 'english',
  });
  const [newFeature, setNewFeature] = useState('');
  const [newKeyword, setNewKeyword] = useState('');
  const [generatedDescription, setGeneratedDescription] = useState(null);
  const [isFavorite, setIsFavorite] = useState(false);
  const [activeTab, setActiveTab] = useState(0);

  const generateMutation = useMutation(
    async (data) => {
      const response = await generatorService.generateDescription(data);
      return response.data;
    },
    {
      onSuccess: (data) => {
        setGeneratedDescription(data);
        toast.success('Description generated successfully!');
      },
      onError: (error) => {
        toast.error(error.response?.data?.detail || 'Failed to generate description');
        console.error('Generation error:', error);
      },
    }
  );

  const handleGenerate = () => {
    if (!productData.product_name.trim()) {
      toast.error('Please enter a product name');
      return;
    }
    if (productData.features.length === 0) {
      toast.error('Please add at least one feature');
      return;
    }

    generateMutation.mutate(productData);
  };

  const handleAddFeature = () => {
    if (newFeature.trim()) {
      setProductData({
        ...productData,
        features: [...productData.features, newFeature.trim()],
      });
      setNewFeature('');
    }
  };

  const handleRemoveFeature = (index) => {
    const features = productData.features.filter((_, i) => i !== index);
    setProductData({ ...productData, features });
  };

  const handleAddKeyword = () => {
    if (newKeyword.trim()) {
      setProductData({
        ...productData,
        keywords: [...productData.keywords, newKeyword.trim()],
      });
      setNewKeyword('');
    }
  };

  const handleRemoveKeyword = (index) => {
    const keywords = productData.keywords.filter((_, i) => i !== index);
    setProductData({ ...productData, keywords });
  };

  const handleDownload = () => {
    if (!generatedDescription) return;

    const content = `
Product Title: ${generatedDescription.title}

Short Description:
${generatedDescription.short_description}

Long Description:
${generatedDescription.long_description}

Key Features:
${generatedDescription.bullet_points.map(point => `• ${point}`).join('\n')}

SEO Title: ${generatedDescription.seo_title}
Meta Description: ${generatedDescription.meta_description}
    `;

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${productData.product_name.replace(/\s+/g, '-').toLowerCase()}-description.txt`;
    a.click();
    URL.revokeObjectURL(url);

    toast.success('Description downloaded!');
  };

  const handleReset = () => {
    setProductData({
      product_name: '',
      category: '',
      brand: '',
      features: [],
      target_audience: 'general audience',
      tone: 'professional',
      keywords: [],
      language: 'english',
    });
    setGeneratedDescription(null);
    setIsFavorite(false);
  };

  const handleCopyAll = () => {
    if (!generatedDescription) return;
    const fullText = `${generatedDescription.title}\n\n${generatedDescription.short_description}\n\n${generatedDescription.long_description}\n\n${generatedDescription.bullet_points.map(p => `• ${p}`).join('\n')}`;
    navigator.clipboard.writeText(fullText);
  };

  return (
    <Container maxWidth="xl" sx={{ py: 4 }}>
      <Typography variant="h3" component="h1" gutterBottom align="center">
        AI Product Description Generator
      </Typography>
      
      <Typography variant="h6" color="textSecondary" align="center" paragraph>
        Generate high-converting product descriptions in seconds
      </Typography>

      {user && (
        <Box sx={{ textAlign: 'center', mb: 3 }}>
          <Chip
            label={`Credits Remaining: ${user.credits || 0}`}
            color={user.credits > 0 ? 'primary' : 'error'}
            variant="outlined"
          />
        </Box>
      )}

      <Grid container spacing={4}>
        {/* Left side - Input form */}
        <Grid item xs={12} md={6}>
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5 }}
          >
            <Paper elevation={3} sx={{ p: 3 }}>
              <Typography variant="h5" gutterBottom>
                Product Details
              </Typography>
              
              <TextField
                fullWidth
                label="Product Name"
                value={productData.product_name}
                onChange={(e) => setProductData({ ...productData, product_name: e.target.value })}
                margin="normal"
                required
              />
              
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Category"
                    value={productData.category}
                    onChange={(e) => setProductData({ ...productData, category: e.target.value })}
                    margin="normal"
                    placeholder="e.g., Electronics"
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Brand"
                    value={productData.brand}
                    onChange={(e) => setProductData({ ...productData, brand: e.target.value })}
                    margin="normal"
                    placeholder="e.g., Apple"
                  />
                </Grid>
              </Grid>

              {/* Features */}
              <Box sx={{ mt: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Features *
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <TextField
                    fullWidth
                    size="small"
                    value={newFeature}
                    onChange={(e) => setNewFeature(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddFeature();
                      }
                    }}
                    placeholder="Add a feature"
                  />
                  <Button
                    variant="outlined"
                    onClick={handleAddFeature}
                    startIcon={<Add />}
                  >
                    Add
                  </Button>
                </Box>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                  {productData.features.map((feature, index) => (
                    <Chip
                      key={index}
                      label={feature}
                      onDelete={() => handleRemoveFeature(index)}
                      deleteIcon={<Close />}
                    />
                  ))}
                </Box>
              </Box>

              <TextField
                fullWidth
                label="Target Audience"
                value={productData.target_audience}
                onChange={(e) => setProductData({ ...productData, target_audience: e.target.value })}
                margin="normal"
                placeholder="e.g., young professionals"
              />

              <FormControl fullWidth margin="normal">
                <InputLabel>Tone</InputLabel>
                <Select
                  value={productData.tone}
                  onChange={(e) => setProductData({ ...productData, tone: e.target.value })}
                  label="Tone"
                >
                  <MenuItem value="professional">Professional</MenuItem>
                  <MenuItem value="casual">Casual</MenuItem>
                  <MenuItem value="luxury">Luxury</MenuItem>
                  <MenuItem value="friendly">Friendly</MenuItem>
                  <MenuItem value="technical">Technical</MenuItem>
                  <MenuItem value="enthusiastic">Enthusiastic</MenuItem>
                  <MenuItem value="minimalist">Minimalist</MenuItem>
                </Select>
              </FormControl>

              <FormControl fullWidth margin="normal">
                <InputLabel>Language</InputLabel>
                <Select
                  value={productData.language}
                  onChange={(e) => setProductData({ ...productData, language: e.target.value })}
                  label="Language"
                >
                  <MenuItem value="english">English</MenuItem>
                  <MenuItem value="spanish">Spanish</MenuItem>
                  <MenuItem value="french">French</MenuItem>
                  <MenuItem value="german">German</MenuItem>
                  <MenuItem value="italian">Italian</MenuItem>
                  <MenuItem value="portuguese">Portuguese</MenuItem>
                  <MenuItem value="dutch">Dutch</MenuItem>
                  <MenuItem value="polish">Polish</MenuItem>
                  <MenuItem value="russian">Russian</MenuItem>
                  <MenuItem value="japanese">Japanese</MenuItem>
                  <MenuItem value="korean">Korean</MenuItem>
                  <MenuItem value="chinese">Chinese</MenuItem>
                  <MenuItem value="arabic">Arabic</MenuItem>
                  <MenuItem value="hindi">Hindi</MenuItem>
                  <MenuItem value="turkish">Turkish</MenuItem>
                </Select>
              </FormControl>

              {/* SEO Keywords */}
              <Box sx={{ mt: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  SEO Keywords
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <TextField
                    fullWidth
                    size="small"
                    value={newKeyword}
                    onChange={(e) => setNewKeyword(e.target.value)}
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddKeyword();
                      }
                    }}
                    placeholder="Add SEO keyword"
                  />
                  <Button
                    variant="outlined"
                    onClick={handleAddKeyword}
                    startIcon={<Add />}
                  >
                    Add
                  </Button>
                </Box>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                  {productData.keywords.map((keyword, index) => (
                    <Chip
                      key={index}
                      label={keyword}
                      onDelete={() => handleRemoveKeyword(index)}
                      deleteIcon={<Close />}
                      color="primary"
                      variant="outlined"
                    />
                  ))}
                </Box>
              </Box>

              <Button
                fullWidth
                variant="contained"
                size="large"
                onClick={handleGenerate}
                disabled={generateMutation.isLoading || user?.credits === 0}
                startIcon={
                  generateMutation.isLoading ? 
                  <CircularProgress size={20} /> : 
                  <AutoAwesome />
                }
                sx={{ mt: 3 }}
              >
                {generateMutation.isLoading ? 
                  'Generating...' : 
                  user?.credits === 0 ? 'No Credits Left' : 'Generate Description'
                }
              </Button>
            </Paper>
          </motion.div>
        </Grid>

        {/* Right side - Output */}
        <Grid item xs={12} md={6}>
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            <Paper elevation={3} sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h5">
                  Generated Description
                </Typography>
                {generatedDescription && (
                  <Box>
                    <Tooltip title={isFavorite ? 'Remove from favorites' : 'Add to favorites'}>
                      <IconButton onClick={() => setIsFavorite(!isFavorite)}>
                        {isFavorite ? <Favorite color="error" /> : <FavoriteBorder />}
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Download">
                      <IconButton onClick={handleDownload}>
                        <Download />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Copy All">
                      <IconButton onClick={handleCopyAll}>
                        <ContentCopy />
                      </IconButton>
                    </Tooltip>
                  </Box>
                )}
              </Box>

              {generatedDescription ? (
                <Box>
                  <Alert severity="success" sx={{ mb: 2 }}>
                    Generated in {generatedDescription.generation_time}s using {generatedDescription.model_used}
                  </Alert>

                  <Typography variant="h6" gutterBottom>
                    {generatedDescription.title}
                  </Typography>

                  <Typography variant="subtitle1" color="primary" gutterBottom sx={{ mt: 2 }}>
                    Short Description
                  </Typography>
                  <Typography variant="body1" paragraph>
                    {generatedDescription.short_description}
                  </Typography>

                  <Divider sx={{ my: 2 }} />

                  <Typography variant="subtitle1" color="primary" gutterBottom>
                    Long Description
                  </Typography>
                  <Typography variant="body2" paragraph>
                    {generatedDescription.long_description}
                  </Typography>

                  <Divider sx={{ my: 2 }} />

                  <Typography variant="subtitle1" color="primary" gutterBottom>
                    Key Features
                  </Typography>
                  <Box component="ul" sx={{ pl: 2 }}>
                    {generatedDescription.bullet_points.map((point, index) => (
                      <li key={index}>
                        <Typography variant="body2">{point}</Typography>
                      </li>
                    ))}
                  </Box>

                  <Divider sx={{ my: 2 }} />

                  <Typography variant="subtitle2" color="textSecondary">
                    SEO Title
                  </Typography>
                  <Typography variant="body2" paragraph>
                    {generatedDescription.seo_title}
                  </Typography>

                  <Typography variant="subtitle2" color="textSecondary">
                    Meta Description
                  </Typography>
                  <Typography variant="body2">
                    {generatedDescription.meta_description}
                  </Typography>
                </Box>
              ) : (
                <Box
                  sx={{
                    height: 400,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    flexDirection: 'column',
                    gap: 2,
                  }}
                >
                  <AutoAwesome sx={{ fontSize: 60, color: 'primary.main' }} />
                  <Typography variant="h6" color="textSecondary">
                    Your generated description will appear here
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    Fill in the product details and click "Generate Description"
                  </Typography>
                </Box>
              )}
            </Paper>
          </motion.div>
        </Grid>
      </Grid>
    </Container>
  );
};

export default Generator;
